import {api} from './api.mjs';
import {layout,queueView,postsView,settingsView,detailView,candidateView,welcome} from './views.mjs';
import {esc,icon,btn,formLink} from './ui.mjs';
import {composePostText} from './domain.mjs';
const $=q=>document.querySelector(q),params=new URLSearchParams(location.search);
const state={view:['posts','settings'].includes(params.get('view'))?params.get('view'):'review',user:null,connections:{},campaign:{},stats:{},rows:[],total:0,hasMore:false,offset:0,bucket:params.get('bucket')||'recommended',direction:'',search:'',detail:null,mine:[],posts:[],busy:false,step:1,draft:{directions:['ugc'],city:'Алматы',language:'ru',experience:'brand',availabilityDays:7},postDraft:{text:'',includeForm:true,scheduledAt:''}};
let debounce,generation=0,returnFocus;
const template='Ищем креаторов для бартера 🇰🇿\n\nСНЕГ* — полоски для домашнего отбеливания зубов. Отправим набор, от вас — честные вертикальные ролики с применением и результатом.\n\nБольшой блог для UGC не нужен. Если хотите публиковать у себя, рассмотрим охваты отдельно.\n\nАлматы, Астана, Шымкент и ещё 13 городов.';
function toast(message,error=false){const t=document.createElement('div');t.className='toast'+(error?' error':'');t.textContent=message;$('#toasts').append(t);setTimeout(()=>t.remove(),6500);}
function show(){const y=window.scrollY;$('#app').innerHTML=layout(state,api.demo||api.localDemo);$('#main').innerHTML=state.user.role==='candidate'?candidateView(state):state.view==='posts'?postsView(state):state.view==='settings'?settingsView(state):queueView(state);if(state.detail)overlays();window.scrollTo(0,y);}
function overlays(){document.body.classList.toggle('drawer-open',!!state.detail);$('#app').inert=!!state.detail;$('#overlay').innerHTML=detailView(state);if(state.detail)$('.drawer-top button')?.focus();}
function closeDetail(){state.detail=null;overlays();returnFocus?.focus?.();window.Telegram?.WebApp?.BackButton?.hide();}
function modal(title,content,formName='confirm',extra=''){const d=document.createElement('dialog');d.className='modal';d.innerHTML=`<div class="modal-head"><span class="eyebrow">СНЕГ* / РЕШЕНИЕ</span><button class="icon-button" data-close-modal aria-label="Закрыть">${icon('close')}</button></div><h2>${title}</h2><form data-form="${formName}" ${extra} class="stack">${content}<p class="form-error" role="alert"></p></form>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();return d;}
function closeModal(){$('dialog')?.close();}
async function run(fn,form){if(state.busy)return;state.busy=true;document.body.classList.add('busy');const submit=form?.querySelector('button[type="submit"]');if(submit)submit.disabled=true;try{await fn();}catch(e){if(form?.isConnected&&form.querySelector('.form-error'))form.querySelector('.form-error').textContent=e.message;else toast(e.message,true);}finally{state.busy=false;document.body.classList.remove('busy');if(submit?.isConnected)submit.disabled=false;}}
function queueParams(){return {queue:state.bucket==='selected'?'selected':state.bucket==='archive'?'archive':'review',bucket:['selected','archive'].includes(state.bucket)?'':state.bucket,direction:state.direction,q:state.search,offset:state.offset};}
async function refresh(more=false){const mine=state.user.role==='candidate';if(mine){state.mine=(await api.mine()).applications;state.campaign=(await api.campaign()).campaign;show();return;}const seq=++generation;const [stats,list,campaign,posts,connections]=await Promise.all([api.overview(),api.list(queueParams()),api.campaign(),api.posts(),api.connections()]);if(seq!==generation)return;state.stats=stats;state.rows=more?[...state.rows,...list.applications]:list.applications;state.total=list.total;state.hasMore=list.hasMore;state.campaign=campaign.campaign;state.posts=posts.posts;state.connections=connections.connections;show();}
async function openDetail(id){returnFocus=document.activeElement;await run(async()=>{state.detail=(await api.detail(id)).application;overlays();const back=window.Telegram?.WebApp?.BackButton;back?.show();});}
function decision(action,id){const a=state.detail;if(!a||a.id!==id)return;let content,title;if(action==='approve'){title='Выбрать '+esc(a.name)+'?';content=`<p>Кандидат получит приглашение в Telegram. Детали передачи товара вы согласуете лично.</p>${a.portfolio.length?'<label class="check-line"><input type="checkbox" name="portfolioReviewed" required>Работу посмотрел(а), кандидат подходит под бриф</label>':''}${btn('Выбрать кандидата','type="submit"','primary full','check')}`;}else if(action==='clarify'){title='Один вопрос — и яснее.';content=`<label>Что нужно уточнить?<textarea name="question" rows="4" minlength="5" required placeholder="Например: пришлите один разговорный ролик с крупным планом.">${esc(a.evaluation?.ai?.question||'')}</textarea></label><p class="fine">Вопрос придёт кандидату в боте. Ответ вернётся в эту карточку.</p>${btn('Отправить вопрос','type="submit"','primary full','arrow')}`;}else if(action==='reject'){title='Пропустить кандидата?';content=`<label>Причина для истории<select name="reason"><option>Не подходит под текущий бриф</option><option>Нужно больше опыта</option><option>Не подходит география</option><option>Уже выбрали нужное количество</option></select></label><p class="fine">Анкета останется в истории. Вы сможете вернуться к ней.</p>${btn('Пропустить','type="submit"','primary full')}`;}else if(action==='mark_sent'){title='Товар уже отправлен?';content=`<p>Это простая отметка менеджера. Доставку вы организуете привычным способом.</p><label class="check-line"><input type="checkbox" name="confirmed" required>Да, товар отправлен этому кандидату</label>${btn('Сохранить отметку','type="submit"','primary full','check')}`;}else{run(async()=>{await api.action(id,action,{},a.version);closeDetail();await refresh();});return;}modal(title,content,'decision',`data-action="${action}" data-id="${id}" data-version="${a.version}"`);}
function collectDraft(form){const f=new FormData(form);for(const[k,v]of f)if(k!=='directions')state.draft[k]=v;if(state.step===1)state.draft.directions=f.getAll('directions');else for(const k of ['adult','closeup','terms','consent','audienceKz'])state.draft[k]=f.has(k);}
function connectGuard(){if(api.demo||api.localDemo){toast('Подключения доступны в рабочем кабинете Telegram.',true);return false;}return true;}
document.addEventListener('click',async event=>{
 const t=event.target.closest('button,a');if(!t)return;if(t.hasAttribute('data-close-modal')){closeModal();return;}if(t.hasAttribute('data-close-detail')){closeDetail();return;}
 if(t.dataset.view){state.view=t.dataset.view;closeDetail();history.replaceState(null,'','/?view='+state.view);await run(()=>refresh());return;}
 if(t.dataset.bucket){state.bucket=t.dataset.bucket;state.offset=0;await run(()=>refresh());return;}
 if(t.dataset.detail){await openDetail(t.dataset.detail);return;}
 if(t.dataset.decision){decision(t.dataset.decision,t.dataset.id);return;}
 if(t.hasAttribute('data-demo-work')){event.preventDefault();toast('Это вымышленная анкета. В рабочем наборе здесь открывается настоящий ролик кандидата.');return;}
 if(t.hasAttribute('data-role-switch')){api.setCandidate(state.user.role!=='candidate');await run(async()=>{const session=await api.session();state.user=session.user;await refresh();});return;}
 if(t.hasAttribute('data-refresh')){await run(()=>refresh());return;}
 if(t.hasAttribute('data-more')){state.offset+=40;await run(()=>refresh(true));return;}
 if(t.hasAttribute('data-form-back')){collectDraft(t.closest('form'));state.step=1;show();return;}
 if(t.hasAttribute('data-post-template')){const f=$('[data-form="post"]');if(f){f.elements.text.value=template;state.postDraft.text=template;f.elements.text.dispatchEvent(new Event('input',{bubbles:true}));}return;}
 if(t.dataset.editPost){const p=state.posts.find(p=>p.id===t.dataset.editPost);state.postDraft={id:p.id,text:p.text,includeForm:false,scheduledAt:p.scheduledAt?new Date(new Date(p.scheduledAt)-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):''};show();$('.post-editor textarea')?.focus();return;}
 if(t.dataset.publish){if(!state.connections.threads){toast('Сначала подключите Threads.',true);return;}modal('Опубликовать сейчас?',`<p>Пост появится в @${esc(state.connections.threadsUsername||'Threads')} без ожидания расписания.</p>${btn('Опубликовать','type="submit"','primary full','arrow')}`,'publish',`data-id="${t.dataset.publish}"`);return;}
 if(t.dataset.cancelPost){await run(async()=>{await api.postAction(t.dataset.cancelPost,'cancel');await refresh();toast('Пост возвращён в черновики.');});return;}
 if(t.hasAttribute('data-authorize')){if(!connectGuard())return;await run(async()=>{const r=await api.integrate('threads/authorize',{});if(window.Telegram?.WebApp?.openLink)window.Telegram.WebApp.openLink(r.url,{try_instant_view:false});else location.href=r.url;});return;}
 if(t.hasAttribute('data-disconnect')){modal('Отключить Threads?',`<p>Новые публикации остановятся. Черновики сохранятся.</p>${btn('Отключить','type="submit"','primary full')}`,'disconnect');return;}
 if(t.hasAttribute('data-ai-disable')){await run(async()=>{await api.integrate('ai',{provider:'rules'});await refresh();});return;}
 if(t.hasAttribute('data-shortlist')){await run(async()=>{await api.shortlist();toast('Подборка появится в Telegram после обработки очереди.');});return;}
 if(t.hasAttribute('data-copy')){if(!t.dataset.copy){toast('Адрес появится в рабочем кабинете Telegram.',true);return;}try{await navigator.clipboard.writeText(t.dataset.copy);toast('Адрес скопирован.');}catch{toast('Выделите адрес и скопируйте его вручную.',true);}return;}
});
document.addEventListener('click',e=>{if(e.target.classList.contains('drawer-backdrop'))closeDetail();});
document.addEventListener('input',e=>{const t=e.target;if(t.hasAttribute('data-search')){state.search=t.value;state.offset=0;clearTimeout(debounce);debounce=setTimeout(async()=>{const seq=++generation;try{const list=await api.list(queueParams());if(seq!==generation)return;state.rows=list.applications;state.total=list.total;state.hasMore=list.hasMore;const focus=t.selectionStart;show();const input=$('[data-search]');input?.focus();input?.setSelectionRange(focus,focus);}catch(err){toast(err.message,true);}},300);}if(t.closest('[data-form="post"]')){const f=t.closest('form');state.postDraft={...state.postDraft,text:f.elements.text.value,includeForm:f.elements.includeForm.checked,scheduledAt:f.elements.scheduledAt.value};const count=$('[data-post-count]');if(count)count.textContent=[...composePostText(state.postDraft.text,formLink(state.botUsername),state.postDraft.includeForm)].length+' / 500';}});
document.addEventListener('change',async e=>{if(e.target.hasAttribute('data-direction')){state.direction=e.target.value;state.offset=0;await run(()=>refresh());}});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const kind=form.dataset.form,f=new FormData(form);if(kind==='application'&&state.step===1){collectDraft(form);if(!state.draft.directions.length){form.querySelector('.form-error').textContent='Выберите хотя бы один формат.';return;}state.step=2;show();window.scrollTo(0,0);return;}
 run(async()=>{
  if(kind==='application'){collectDraft(form);await api.submit({...state.draft,portfolio:String(state.draft.portfolio||'').split(/\n+/).filter(Boolean),views:state.draft.views||null,followers:state.draft.followers||null});state.draft={};await refresh();window.scrollTo(0,0);toast('Анкета отправлена.');}
  if(kind==='answer'){const a=state.mine[0];await api.action(a.id,'answer',{answer:f.get('answer')},a.version);await refresh();toast('Ответ передан менеджеру.');}
  if(kind==='decision'){const action=form.dataset.action,payload=Object.fromEntries(f);if(action==='approve')payload.portfolioReviewed=true;if(action==='mark_sent')payload.confirmed=f.has('confirmed');await api.action(form.dataset.id,action,payload,Number(form.dataset.version));closeModal();closeDetail();await refresh();toast('Решение сохранено.');}
  if(kind==='post'){const intent=event.submitter?.value||'draft';await api.savePost({id:state.postDraft.id,text:f.get('text'),includeForm:f.has('includeForm'),status:intent,scheduledAt:f.get('scheduledAt')?new Date(f.get('scheduledAt')).toISOString():null});state.postDraft={text:'',includeForm:true,scheduledAt:''};await refresh();toast(intent==='scheduled'?'Публикация поставлена в расписание.':'Черновик сохранён.');}
  if(kind==='publish'){await api.postAction(form.dataset.id,'publish');closeModal();await refresh();toast('Пост передан в очередь публикации.');}
  if(kind==='campaign'){await api.updateCampaign({...Object.fromEntries(f),limit:Number(f.get('limit')),minViews:Number(f.get('minViews')),active:f.has('active'),productionApproved:f.has('productionApproved')});await refresh();toast('Условия сохранены.');}
  if(kind==='threads-app'||kind==='threads-token'){if(!connectGuard())return;await api.integrate(kind==='threads-app'?'threads/app':'threads/token',Object.fromEntries(f));form.reset();await refresh();toast(kind==='threads-app'?'Приложение сохранено. Теперь нажмите «Войти в Threads».':'Аккаунт Threads подключён.');}
  if(kind==='ai'){if(!connectGuard())return;toast('Проверяем ключ и ответ модели…');await api.integrate('ai',{...Object.fromEntries(f),provider:'gemini'});form.reset();await refresh();toast('ИИ подключён. Новые анкеты будут получать резюме.');}
  if(kind==='disconnect'){await api.integrate('threads/disconnect',{});closeModal();await refresh();toast('Threads отключён.');}
 },form);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('dialog'))closeDetail();if(e.key==='Tab'&&state.detail&&!$('dialog')){const focusable=[...$('.drawer').querySelectorAll('a,button,input,textarea,select')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus();}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user&&!state.busy&&!$('dialog')&&state.view!=='settings'&&state.user.role!=='candidate')run(()=>refresh());});
async function boot(){window.Telegram?.WebApp?.ready();window.Telegram?.WebApp?.expand();window.Telegram?.WebApp?.BackButton?.onClick(closeDetail);try{const session=await api.session();state.user=session.user;state.connections=session.connections;state.botUsername=session.botUsername;await refresh();const candidate=params.get('candidate');if(candidate&&state.user.role!=='candidate')await openDetail(candidate);}catch(e){if(e.status===401){try{const p=await api.public();state.campaign=p.campaign;state.botUsername=p.botUsername;$('#app').innerHTML=welcome(state);}catch{$('#app').innerHTML='<main class="application-wrap"><h1>Связь прервалась.</h1><p>Откройте приложение из бота ещё раз.</p></main>';}}else{$('#app').innerHTML=`<main class="application-wrap"><h1>Нужен ещё один шаг.</h1><p>${esc(e.message)}</p>${btn('Попробовать снова','data-retry','primary')}</main>`;$('[data-retry]').onclick=()=>location.reload();}}}
boot();
